\begin{align*} \label{eq:1} \det(A) &= \sec^2 x \begin{vmatrix} \cos^2 x & \csc^2 x \\ \cos^2 x & \cot^2 x \end{vmatrix} - 1 \begin{vmatrix} \cos^2 x & \csc^2 x \\ 1 & \cot^2 x \end{vmatrix} + 1 \begin{vmatrix} \cos^2 x & \cos^2 x \\ 1 & \cos^2 x \end{vmatrix} \\ &= \sec^2 x (\cos^2 x \cot^2 x - \csc^2 x \cos^2 x) - (\cos^2 x \cot^2 x - \csc^2 x) + (\cos^4 x - \cos^2 x) \\ &= \sec^2 x \cos^2 x (\cot^2 x - \csc^2 x) - \cos^2 x \cot^2 x + \csc^2 x + \cos^4 x - \cos^2 x \\ &= \sec^2 x \cos^2 x \left( \frac{\cos^2 x}{\sin^2 x} - \frac{1}{\sin^2 x} \right) - \cos^2 x \frac{\cos^2 x}{\sin^2 x} + \frac{1}{\sin^2 x} + \cos^4 x - \cos^2 x \\ &= \sec^2 x \cos^2 x \frac{\cos^2 x - 1}{\sin^2 x} - \frac{\cos^4 x}{\sin^2 x} + \frac{1}{\sin^2 x} + \cos^4 x - \cos^2 x \end{align*}
Since $\sin^2 x = 1 - \cos^2 x$,
\begin{align*} \det(A) &= \frac{\sec^2 x \cos^2 x (\cos^2 x - 1)}{\sin^2 x} - \frac{\cos^4 x}{\sin^2 x} + \frac{1}{\sin^2 x} + \cos^4 x - \cos^2 x \\ &= \frac{\sec^2 x \cos^2 x (-\cos(2x))}{\sin^2 x} - \frac{\cos^4 x}{\sin^2 x} + \frac{1}{\sin^2 x} + \cos^4 x - \cos^2 x \\ &= \frac{\sec^2 x \cos^2 x (-\cos(2x))}{\sin^2 x} - \frac{\cos^4 x}{\sin^2 x} + \frac{1}{\sin^2 x} + \cos^4 x - \cos^2 x \end{align*}

Instead, let's compute the determinant directly:
\begin{align*} \det(A) &= \sec^2 x \left(\cos^2 x \cot^2 x - \csc^2 x \cos^2 x\right) - 1(\cos^2 x \cot^2 x - \csc^2 x) + 1(\cos^4 x - \cos^2 x) \\ &= \sec^2 x \left(\cos^2 x \frac{\cos^2 x}{\sin^2 x} - \frac{1}{\sin^2 x} \cos^2 x\right) - \cos^2 x \frac{\cos^2 x}{\sin^2 x} + \csc^2 x + \cos^4 x - \cos^2 x \\ &= \sec^2 x \left(\frac{\cos^4 x}{\sin^2 x} - \frac{\cos^2 x}{\sin^2 x}\right) - \frac{\cos^4 x}{\sin^2 x} + \csc^2 x + \cos^4 x - \cos^2 x \\ &= \frac{\sec^2 x \cos^4 x}{\sin^2 x} - \frac{\sec^2 x \cos^2 x}{\sin^2 x} - \frac{\cos^4 x}{\sin^2 x} + \csc^2 x + \cos^4 x - \cos^2 x \\ &= \frac{\frac{1}{\cos^2 x} \cos^4 x}{\sin^2 x} - \frac{\frac{1}{\cos^2 x} \cos^2 x}{\sin^2 x} - \frac{\cos^4 x}{\sin^2 x} + \csc^2 x + \cos^4 x - \cos^2 x \\ &= \frac{\cos^2 x}{\sin^2 x} - \frac{1}{\sin^2 x} - \frac{\cos^4 x}{\sin^2 x} + \csc^2 x + \cos^4 x - \cos^2 x \\ &= \frac{\cos^2 x}{\sin^2 x} - \frac{1}{\sin^2 x} - \frac{\cos^4 x}{\sin^2 x} + \csc^2 x + \cos^4 x - \cos^2 x \end{align*}
Let $x = \frac{\pi}{4}$. Then $\cos x = \frac{1}{\sqrt{2}}$ and $\sin x = \frac{1}{\sqrt{2}}$.
