\begin{align*} A &= \begin{pmatrix} 2 & 1 & 1 \\ \frac{1}{2} & \frac{1}{2} & 2 \\ 1 & \frac{1}{2} & 1 \end{pmatrix} \\ \det(A) &= 2 \left( \frac{1}{2} \cdot 1 - 2 \cdot \frac{1}{2} \right) - 1 \left( \frac{1}{2} \cdot 1 - 2 \cdot 1 \right) + 1 \left( \frac{1}{2} \cdot \frac{1}{2} - \frac{1}{2} \cdot 1 \right) \\ &= 2 \left( \frac{1}{2} - 1 \right) - 1 \left( \frac{1}{2} - 2 \right) + 1 \left( \frac{1}{4} - \frac{1}{2} \right) \\ &= 2 \left( -\frac{1}{2} \right) - 1 \left( -\frac{3}{2} \right) + 1 \left( -\frac{1}{4} \right) \\ &= -1 + \frac{3}{2} - \frac{1}{4} \\ &= \frac{-4 + 6 - 1}{4} = \frac{1}{4} \end{align*}

